package clusterdata.datatypes;

import java.io.Serializable;

public class TaskEvent implements Serializable {

    // Event type constants
    public static final int SUBMIT = 0;
    public static final int SCHEDULE = 1;
    public static final int EVICT = 2;
    public static final int FAIL = 3;
    public static final int FINISH = 4;
    public static final int KILL = 5;

    private long timestamp;
    private String missingInfo;
    private long jobId;
    private long taskIndex;
    private Long machineId;
    private int eventType;
    private String username;
    private int schedulingClass;
    private int priority;
    private Double cpuRequest;
    private Double memoryRequest;
    private Double diskRequest;
    private Integer constraint;

    public TaskEvent() {}

    public TaskEvent(long timestamp, String missingInfo, long jobId, long taskIndex,
                     Long machineId, int eventType, String username, int schedulingClass,
                     int priority, Double cpuRequest, Double memoryRequest,
                     Double diskRequest, Integer constraint) {
        this.timestamp = timestamp;
        this.missingInfo = missingInfo;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.machineId = machineId;
        this.eventType = eventType;
        this.username = username;
        this.schedulingClass = schedulingClass;
        this.priority = priority;
        this.cpuRequest = cpuRequest;
        this.memoryRequest = memoryRequest;
        this.diskRequest = diskRequest;
        this.constraint = constraint;
    }

    public static TaskEvent fromString(String line) {
        String[] parts = line.split(",", -1);
        if (parts.length < 6) {
            return null;
        }

        try {
            long timestamp = parts[0].isEmpty() ? 0L : Long.parseLong(parts[0]);
            String missingInfo = parts[1];
            long jobId = parts[2].isEmpty() ? 0L : Long.parseLong(parts[2]);
            long taskIndex = parts[3].isEmpty() ? 0L : Long.parseLong(parts[3]);
            Long machineId = parts[4].isEmpty() ? null : Long.parseLong(parts[4]);
            int eventType = parts[5].isEmpty() ? -1 : Integer.parseInt(parts[5]);
            String username = parts.length > 6 ? parts[6] : "";
            int schedulingClass = parts.length > 7 && !parts[7].isEmpty() ? Integer.parseInt(parts[7]) : 0;
            int priority = parts.length > 8 && !parts[8].isEmpty() ? Integer.parseInt(parts[8]) : 0;
            Double cpuRequest = parts.length > 9 && !parts[9].isEmpty() ? Double.parseDouble(parts[9]) : null;
            Double memoryRequest = parts.length > 10 && !parts[10].isEmpty() ? Double.parseDouble(parts[10]) : null;
            Double diskRequest = parts.length > 11 && !parts[11].isEmpty() ? Double.parseDouble(parts[11]) : null;
            Integer constraint = parts.length > 12 && !parts[12].isEmpty() ? Integer.parseInt(parts[12]) : null;

            return new TaskEvent(timestamp, missingInfo, jobId, taskIndex, machineId, eventType,
                    username, schedulingClass, priority, cpuRequest, memoryRequest, diskRequest, constraint);
        } catch (NumberFormatException e) {
            return null;
        }
    }

    public long getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(long timestamp) {
        this.timestamp = timestamp;
    }

    public String getMissingInfo() {
        return missingInfo;
    }

    public void setMissingInfo(String missingInfo) {
        this.missingInfo = missingInfo;
    }

    public long getJobId() {
        return jobId;
    }

    public void setJobId(long jobId) {
        this.jobId = jobId;
    }

    public long getTaskIndex() {
        return taskIndex;
    }

    public void setTaskIndex(long taskIndex) {
