        this.constraint = constraint;
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "timestamp=" + timestamp +
                ", jobId=" + jobId +
                ", taskIndex=" + taskIndex +
                ", eventType=" + eventType +
                '}';
    }
